{
  "mechanisms": [
    {
      "name": "mb_mf_mixture",
      "title": "MB/MF mixture weight",
      "description": "Combines model-based and model-free Q-values for stage 1 choices using a weighting parameter.",
      "params": [
        {
          "name": "w",
          "bounds": [0, 1]
        }
      ],
      "evidence": "q_stage1_net = w * q_stage1_mb + (1 - w) * q_stage1_mf",
      "expressible_in_slots": true
    },
    {
      "name": "eligibility_trace",
      "title": "Eligibility trace",
      "description": "Updates the stage 1 model-free Q-value using the stage 2 reward prediction error scaled by an eligibility trace parameter.",
      "params": [
        {
          "name": "lam",
          "bounds": [0, 1]
        }
      ],
      "evidence": "q_stage1_mf[action_1[trial]] += alpha * lam * delta_stage2",
      "expressible_in_slots": true
    },
    {
      "name": "reward_dependent_stickiness",
      "title": "Reward-dependent stickiness",
      "description": "Applies separate choice stickiness bonuses to the previously chosen stage 1 action depending on whether the previous trial was rewarded or unrewarded.",
      "params": [
        {
          "name": "rep_win",
          "bounds": [-5, 5]
        },
        {
          "name": "rep_lose",
          "bounds": [-5, 5]
        }
      ],
      "evidence": "stickiness = np.zeros(2)\nif last_action_1 != -1:\n    if last_reward == 1:\n        stickiness[last_action_1] = rep_win\n    elif last_reward == 0:\n        stickiness[last_action_1] = rep_lose\n        \nq1_logits = beta_1 * q_stage1_net + stickiness",
      "expressible_in_slots": true
    }
  ]
}
